solution:
world_data = {
    'Egypt': {'pop_m': 109, 'tags': {'river', 'continent', 'desert'}},
    'Iceland': {'pop_m': 0.3, 'tags': {'island', 'volcano'}}
}

REQUIRED_TAGS = {'capital', 'continent', 'river'}
all_geographic_features = set()

for country, facts in world_data.items():
    # Check population size
    if facts['pop_m'] < 10:
        print(f'Small Population Alert: {country}')

    # Identify missing research categories
    missing = REQUIRED_TAGS - facts['tags']
    if missing:
        print(f'{country} is missing info for: {missing}')

    # Consolidate all unique features
    all_geographic_features = all_geographic_features | facts['tags']

print(f'Master List of Geographic Features: {all_geographic_features}')

expectedOutput:
Small Population Alert: Iceland
Egypt is missing info for: {'capital'}
Iceland is missing info for: {'capital', 'river'}
Master List of Geographic Features: {'volcano', 'desert', 'continent', 'island', 'river'}

